import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

type SidebarItems = Extract<SidebarsConfig[string], unknown[]>;
type Item = {
  type: string;
  label?: string;
  className?: string;
  items?: Item[];
  [key: string]: unknown;
};

// Generated by docusaurus-plugin-typedoc into ./api on each build: one
// category per package (labelled with the full npm name), holding one
// category per kind ("Classes", "Interfaces", ...).
// eslint-disable-next-line @typescript-eslint/no-require-imports
const packages: Item[] = require('./api/typedoc-sidebar.cjs');

// Kind groups are flattened, and each entry gets a kind badge instead
// (src/css/theme/api.css), like TypeDoc's HTML theme.
const KINDS: Record<string, string> = {
  Namespaces: 'namespace',
  Enumerations: 'enum',
  Classes: 'class',
  Interfaces: 'interface',
  'Type Aliases': 'type',
  Variables: 'variable',
  Functions: 'function',
};

const withClass = (item: Item, className: string): Item => ({
  ...item,
  className: [item.className, className].filter(Boolean).join(' '),
});

function moduleItems(items: Item[] = []): Item[] {
  return items.flatMap((item) => {
    const kind =
      item.type === 'category' && item.label ? KINDS[item.label] : undefined;
    if (kind) {
      return (item.items ?? []).map((entry) =>
        withClass(entry, `api-kind api-kind-${kind}`),
      );
    }
    // A package with several entry points (plugin-vite) has a category per module.
    if (item.type === 'category') return [module(item, item.label ?? '')];
    return [item];
  });
}

const module = (item: Item, label: string): Item =>
  withClass(
    { ...item, label, items: moduleItems(item.items) },
    'api-kind api-kind-module',
  );

const shortName = (item: Item) =>
  (item.label ?? '').replace(/^@electron-forge\//, '');

const pkg = (name: string, label: string): Item => {
  const item = packages.find((p) => shortName(p) === name);
  if (!item) throw new Error(`No API docs generated for ${name}`);
  return module(item, label);
};

// Makers, plugins and publishers are grouped, with the group's prefix
// dropped from each label (Makers > zip, not Makers > maker-zip).
const group = (label: string, prefix: string): Item => ({
  type: 'category',
  label,
  collapsed: true,
  items: packages
    .filter((p) => shortName(p).startsWith(prefix))
    .map((p) => module(p, shortName(p).slice(prefix.length))),
});

const sidebars: SidebarsConfig = {
  api: [
    { type: 'doc', id: 'index', label: 'Overview' },
    pkg('core', 'Core'),
    pkg('shared-types', 'Shared types'),
    group('Makers', 'maker-'),
    group('Plugins', 'plugin-'),
    group('Publishers', 'publisher-'),
  ] as SidebarItems,
};

export default sidebars;
